API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Routing_Engine, "Routing Engine", ".NET YARP", "Handles incoming API requests and directs them to appropriate backend services.")
    Component(Authentication_Authorization_Filter, "Authentication & Authorization Filter", ".NET Middleware", "Validates user tokens and secures API routes.")
    Component(Rate_Limiting_Resiliency_Policy_Middleware, "Rate Limiting & Resiliency Policy Middleware", ".NET Polly", "Applies rate limiting and transient fault handling policies for slow responses.")
    Component(Transformation_Protocol_Bridge, "Transformation & Protocol Bridge", ".NET Core", "Translates and bridges protocols between incoming requests and backend services.")
}

Rel(Routing_Engine, Transformation_Protocol_Bridge, "Passes raw requests", "In-memory")

@enduml

Integration Message Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(integration_message_broker, "Integration Message Broker") {
    Component(Claim_Routing_Topic, "Claim Routing Topic", "Azure Service Bus Topic", "Publishes domain events and satisfies zero-data-loss requirements.")
    Component(Session_Processor, "Session Processor", "Azure Service Bus Session Processor", "Enforces ordered delivery per session ID.")
    Component(Dead_Letter_Subsystem, "Dead-Letter Subsystem", "Azure Service Bus Dead-Letter Queue", "Handles undeliverable messages and duplicate detection.")
}

Rel(Claim_Routing_Topic, Session_Processor, "Enforces ordered delivery per session ID", "AMQP")

@enduml
